if (!input || typeof input.graphSpec !== 'string') { throw new Error('Missing or invalid graphSpec'); }
let parsed;
try { parsed = JSON.parse(input.graphSpec); } catch (e) { throw new Error('Invalid JSON for graphSpec'); }
if (!Array.isArray(parsed.nodes) || !Array.isArray(parsed.edges)) { throw new Error('graphSpec must have nodes and edges arrays'); }
globalThis.graph = parsed;

const mod = await import('dependency-graph');
const DepGraph = mod.DepGraph || mod.default?.DepGraph || mod.default;
const dg = new DepGraph();
globalThis.graph.nodes.forEach(n => dg.addNode(n));
globalThis.graph.edges.forEach(e => dg.addDependency(e[0], e[1]));
globalThis.order = dg.overallOrder().join(',');
